BEGIN;
INSERT INTO "FileUploadGrant" (id,"organizationId","labId","createdByMemberId","boundaryId",purpose,"targetType","targetId",provider,"providerFileKey","correlationId","createdAt","updatedAt","expiresAt","caseClinicalValidatedSuffix") VALUES ('suffix-positive-2','suffix-org','suffix-lab','suffix-member','N-FILE-110','case.asset.add.stage','case','suffix-case','UPLOADTHING','key-positive-2','positive-2',(now() at time zone 'UTC')-interval '1 minute',(now() at time zone 'UTC'),(now() at time zone 'UTC')+interval '1 hour','JPEG');
INSERT INTO "CaseClinicalUploadEvidence" ("uploadGrantId","organizationId","labId","caseId",provider,"providerObjectKey","clinicalPurpose","verifiedFormat","validatedSuffix","measuredSizeBytes",width,height,"contentSha256","validationProfile","validatorVersion","codecBackend","codecPackageVersion","codecLibraryVersion","codecRuntimeSha256","sourceComponents","isProgressive","validatedAt") VALUES ('suffix-positive-2','suffix-org','suffix-lab','suffix-case','UPLOADTHING','key-positive-2','CLINICAL_REFERENCE_PHOTOGRAPH','JPEG','JPEG',1234,16,16,repeat('a',64),'JPEG_CLINICAL_V1_S001','LABOS_S001_JULUSIAN_V1','JULUSIAN_TURBOJPEG','3.0.1','3.1.3',repeat('b',64),3,false,now());
